html:
{%- set data = ti_record(doc) -%}
<!doctype html><html><head><meta charset="utf-8"><style>{{ ti_print_css() }}</style>
<style>.print-format { page-width: 215.9mm; page-height: 279.4mm; orientation: Portrait; margin-top: 10mm; margin-bottom: 10mm; margin-left: 10mm; margin-right: 10mm; }
.print-format .ti-slip .ti-table { font-size: {{ data.font_pt }}pt; }
.print-format .ti-slip .ti-table .ti-head-row th { font-size: {{ data.head_font_pt }}pt; }
</style></head><body><div class="ti-print ti-sheet ti-slip">
{% if data.watermark %}<div class="ti-watermark">{{ data.watermark|e }}</div>{% endif %}
<table class="ti-table ti-fixed"><colgroup><col style="width:{{ data.seq_width_pt }}pt">{% for column in data.columns %}<col{% if column.width_pt %} style="width:{{ column.width_pt }}pt"{% endif %}>{% endfor %}</colgroup>
<thead><tr class="ti-title-row"><th colspan="{{ data.columns|length + 1 }}"><span class="ti-title">{{ data.date|e }}【{{ data.title_location|e }}】{{ data.kind_label|e }}登记表</span><span class="ti-docno">单号 {{ data.name|e }}</span></th></tr>
<tr class="ti-head-row"><th class="ti-seq">#</th>{% for column in data.columns %}<th class="{% if column.is_main %}ti-main{% elif column.wrap %}ti-wrap{% else %}ti-nowrap{% endif %}">{{ column.label|e }}</th>{% endfor %}</tr></thead>
<tbody>{% for line in data.lines %}<tr><td class="ti-seq">{{ loop.index }}</td>{% for column in data.columns %}<td class="{% if column.is_main %}ti-main{% elif column.wrap %}ti-wrap{% else %}ti-nowrap{% endif %}{% if column.align == 'number' %} ti-num{% endif %}{% if column.key in ['unit'] %} ti-center{% endif %}">{{ line.get(column.key, '')|e }}</td>{% endfor %}</tr>{% endfor %}
<tr class="ti-subtotal"><td class="ti-seq"></td><td colspan="{{ data.columns|length }}">小计：{{ data.line_count }} 行{% if data.doctype != 'Stock Reconciliation' %}{% for unit, total in data.totals.items() %} · {{ total|e }} {{ unit|e }}{% endfor %}{% endif %}{% if data.doctype == 'Stock Reconciliation' %}{% for unit, totals in data.count_totals.items() %} · {{ unit|e }} 账面 {{ totals.book|e }} / 实盘 {{ totals.actual|e }} / 差异 {{ totals.difference|e }}{% endfor %}{% endif %}</td></tr>
{% if data.notes or data.source or data.purpose or data.borrower or data.activity_title %}<tr class="ti-note-row"><td colspan="{{ data.columns|length + 1 }}"><strong>说明：</strong>{% if data.borrower %}借用人 {{ data.borrower|e }}；{% endif %}{% if data.activity_title %}活动 {{ data.activity_title|e }}；{% endif %}{% if data.source %}来源 {{ data.source|e }}；{% endif %}{% if data.purpose %}用途 {{ data.purpose|e }}；{% endif %}{{ data.notes|e }}</td></tr>{% endif %}
</tbody></table>
<div class="ti-slip-signatures">{% for label in data.signature_labels %}<span>{{ label|e }}：{% if data.signature_names[loop.index0] %}<strong>{{ data.signature_names[loop.index0]|e }}</strong>{% endif %}　签名 ________　日期 ________</span>{% endfor %}</div>
</div></body></html>
